INSERT INTO "public"."portal_content" ("id", "page", "section", "title", "slug", "content", "status", "created_at", "updated_at") VALUES
	('34b5a62b-851d-4847-9018-1680c23554b6', 'default', 'main', 'Nuzultrip Investor Portal', 'default', '{"docs": [{"id": "pitch-deck", "name": "Pitch Deck ", "size": "0.4 MB", "type": "PDF", "pages": 23, "embedUrl": "https://docs.google.com/document/d/1GaVIrf93hH3ZNoNqk7NAtlrf0WWqWhE3/edit?usp=sharing&ouid=114749519026638979975&rtpof=true&sd=true", "fileName": "Annisa IstiQomah Nur Aqila 202305009.pdf", "coverImageUrl": ""}, {"id": "investment-memo", "name": "Investment Memorandum (IM)", "size": "8.7 MB", "type": "PDF", "pages": 48, "embedUrl": "https://drive.google.com/file/d/1AmYTYSNyMVT5KcPMLI4zftyrGn1jtiQ6/view?usp=sharing"}, {"id": "exec-summary", "name": "Ringkasan Eksekutif", "size": "1.1 MB", "type": "PDF", "pages": 6}, {"id": "financial-model", "name": "Financial Projections Model", "size": "2.3 MB", "type": "XLSX", "pages": 0, "embedUrl": "https://docs.google.com/document/d/1GaVIrf93hH3ZNoNqk7NAtlrf0WWqWhE3/edit?usp=sharing&ouid=114749519026638979975&rtpof=true&sd=true"}], "faqs": [{"a": "Indonesia adalah pasar jamaah Umrah terbesar di dunia namun masih sangat terfragmentasi. Nuzultrip adalah PPIU pertama yang dibangun dari hari pertama dengan standar institusional, teknologi terintegrasi, dan modal yang memadai untuk mendominasi pasar.", "q": "Apa inti tesis investasi Nuzultrip?", "id": "faq1"}, {"a": "Kami menggalang Rp 5 Miliar untuk: Ekspansi Cabang 40% (Rp 2M), Teknologi & Sistem 25% (Rp 1,25M), Modal Kerja 20% (Rp 1M), Pemasaran & Branding 15% (Rp 750 Juta).", "q": "Berapa target penggalangan modal dan untuk apa?", "id": "faq2"}, {"a": "Minimum investasi Rp 500 Juta dengan 30% saham biasa ditawarkan. Valuasi pre-money Rp 25 Miliar.", "q": "Berapa minimum investasi dan struktur sahamnya?", "id": "faq3"}, {"a": "Target IRR 25-35% dalam 5 tahun. Dividen mulai tahun ke-2 sebesar 30-40% laba bersih. Multiple on Investment 3-5x skenario dasar.", "q": "Apa proyeksi return bagi investor?", "id": "faq4"}, {"a": "Tersedia 4 jalur exit: Buyback Founder (Tahun 2-3), Penjualan Saham Sekunder (Tahun 3-4), Akuisisi Strategis (Tahun 4-5), dan IPO IDX (Tahun 5+).", "q": "Apa jalur keluar bagi investor strategis?", "id": "faq5"}, {"a": "Nuzultrip (PT. Swarna Dipa Wisata) memiliki lisensi PPIU resmi dari Kementerian Agama dan Umrah Republik Indonesia.", "q": "Lisensi PPIU apa yang dimiliki Nuzultrip?", "id": "faq6"}, {"a": "Perusahaan menerapkan 5 Prinsip GCG (TARIF): Transparansi, Akuntabilitas, Responsibilitas, Independensi, dan Fairness dengan laporan berkala kepada investor.", "q": "Bagaimana struktur tata kelola perusahaan?", "id": "faq7"}, {"a": "Ya. Investor terakreditasi dapat meminta akses data room lengkap termasuk laporan keuangan, proyeksi model, dan perjanjian NDA melalui halaman kontak.", "q": "Apakah tersedia data room dan informasi lebih lanjut?", "id": "faq8"}], "kpis": [{"id": "funding", "num": "Rp 5 M", "sub": "Putaran Strategis 2026", "icon": "DollarSign", "label": "Target Pendanaan", "order": 1, "accent": true, "prefix": "", "status": "aktif", "suffix": "", "dbField": "", "dbTable": "", "refDate": "", "refLink": "", "tooltip": "", "category": "investasi", "decimals": 0, "cardColor": "merah", "refSource": "Laporan Internal", "dataSource": "manual", "visibility": {"dataRoom": false, "dashboard": true, "mobileApp": true, "pitchDeck": true, "memorandum": true, "landingPortal": true, "companyProfile": false, "portalInvestor": true}, "apiEndpoint": "", "description": "Total target penggalangan modal putaran strategis 2026", "valueFormat": "miliar", "internalNote": "", "publishStatus": "dipublikasikan"}, {"id": "equity", "num": "30%", "sub": "Kepemilikan strategis", "icon": "PieChart", "label": "Saham Ditawarkan", "order": 2, "accent": false, "prefix": "", "status": "aktif", "suffix": "", "dbField": "", "dbTable": "", "refDate": "", "refLink": "", "tooltip": "", "category": "investasi", "decimals": 0, "cardColor": "default", "refSource": "Laporan Internal", "dataSource": "manual", "visibility": {"dataRoom": false, "dashboard": true, "mobileApp": true, "pitchDeck": true, "memorandum": true, "landingPortal": true, "companyProfile": false, "portalInvestor": true}, "apiEndpoint": "", "description": "Persentase saham yang ditawarkan kepada investor strategis", "valueFormat": "persentase", "internalNote": "", "publishStatus": "dipublikasikan"}, {"id": "tam", "num": "Rp 25 T", "sub": "Proyeksi TAM 2029", "icon": "TrendingUp", "label": "Ukuran Pasar", "order": 3, "accent": false, "prefix": "", "status": "aktif", "suffix": "", "dbField": "", "dbTable": "", "refDate": "", "refLink": "", "tooltip": "", "category": "market", "decimals": 0, "cardColor": "default", "refSource": "Kementerian Agama", "dataSource": "manual", "visibility": {"dataRoom": false, "dashboard": true, "mobileApp": true, "pitchDeck": true, "memorandum": true, "landingPortal": true, "companyProfile": false, "portalInvestor": true}, "apiEndpoint": "", "description": "Total addressable market perjalanan umrah Indonesia 2029", "valueFormat": "triliun", "internalNote": "", "publishStatus": "dipublikasikan"}, {"id": "irr", "num": "~25%", "sub": "Proyeksi 5 Tahun", "icon": "BarChart2", "label": "Target IRR", "order": 4, "accent": false, "prefix": "", "status": "aktif", "suffix": "", "dbField": "", "dbTable": "", "refDate": "", "refLink": "", "tooltip": "", "category": "financial", "decimals": 0, "cardColor": "default", "refSource": "Laporan Internal", "dataSource": "manual", "visibility": {"dataRoom": false, "dashboard": true, "mobileApp": true, "pitchDeck": true, "memorandum": true, "landingPortal": true, "companyProfile": false, "portalInvestor": true}, "apiEndpoint": "", "description": "Internal rate of return target dalam 5 tahun", "valueFormat": "persentase", "internalNote": "", "publishStatus": "dipublikasikan"}], "team": [{"id": "ceo", "exp": "Kepemimpinan strategis, keahlian industri perjalanan Islam, tata kelola perusahaan", "name": "[PENDING DECISION]", "role": "Founder & Chief Executive Officer", "order": 0, "photo": "https://images.unsplash.com/photo-1513072064285-240f87fa81e8?w=400&h=400&fit=crop&auto=format", "linkedin": ""}, {"id": "coo", "exp": "Manajemen operasional, kepatuhan regulasi PPIU, layanan jamaah", "name": "Maulana M", "role": "Chief Operating Officer", "order": 1, "photo": "https://drive.google.com/file/d/1S2fqvKrGqTT72_weDOz5YOsgbgpD15Ei/view?usp=sharing", "linkedin": ""}, {"id": "cfo", "exp": "Keuangan korporat, hubungan investor, pelaporan keuangan", "name": "[PENDING DECISION]", "role": "Chief Financial Officer", "order": 2, "photo": "https://images.unsplash.com/photo-1779700210487-a01758a3c55a?w=400&h=400&fit=crop&auto=format", "linkedin": ""}, {"id": "cco", "exp": "Strategi penjualan, pengembangan jaringan afiliasi, pemasaran", "name": "[PENDING DECISION]", "role": "Chief Commercial Officer", "order": 3, "photo": "https://images.unsplash.com/photo-1775492783108-5714035b298b?w=400&h=400&fit=crop&auto=format", "linkedin": ""}], "company": {"hq": "Makassar, Indonesia", "irr": "~25%", "tam": "Rp 25 Triliun", "name": "PT. Swarna Dipa Wisata", "brand": "Nuzultrip", "email": "investor@nuzultrip.co.id", "phone": "+62858 9363 8023", "address": "Jl. [Alamat Kantor], Makassar, Sulawesi Selatan 90111", "founded": "2024", "license": "PPIU — Kementerian Haji dan Umrah", "whatsapp": "+62858 9363 8023", "valuation": "Rp 25.000.000.000", "equityOffered": "30%", "minInvestment": "Rp 500.000.000", "targetFunding": "Rp 5.000.000.000"}, "content": {"ctaDesc": "Pilih cara terbaik untuk memulai percakapan dengan tim Investor Relations kami.", "gcgDesc": "PT. Swarna Dipa Wisata menerapkan 5 Prinsip Good Corporate Governance (TARIF) sebagaimana diatur oleh perundang-undangan yang berlaku di Indonesia.", "exitDesc": "Empat jalur exit dengan timeline yang realistis dan valuasi yang terukur.", "fundsSub": "Setiap rupiah dialokasikan untuk menghasilkan dampak maksimum.", "riskDesc": "Kami mengidentifikasi risiko lebih awal dan membangun mitigasi ke dalam operasi inti.", "techDesc": "Infrastruktur digital end-to-end yang memungkinkan skalabilitas nasional.", "execQuote": "PPIU pertama Indonesia yang dibangun dari Hari 1 dengan standar tata kelola, teknologi, dan modal institusional.", "ctaHeading": "Siap untuk Terlibat?", "faqHeading": "Pertanyaan yang Sering Diajukan", "gcgHeading": "Tata Kelola Perusahaan", "thesisDesc": "Nuzultrip hadir di persimpangan pasar besar, kesenjangan struktural, dan tim yang tepat.", "exitHeading": "Jalur Keluar yang Jelas\nbagi Investor", "heroTagline": "Private Placement · Series Seed 2026", "navCtaLabel": "Jadwalkan Pertemuan", "riskHeading": "Risiko Diidentifikasi & Dimitigasi", "roadmapDesc": "Pendekatan bertahap untuk ekspansi nasional, adopsi teknologi, dan skala keuangan — dieksekusi dengan disiplin institusional.", "techHeading": "Teknologi sebagai\nKeunggulan Operasional", "thesisQuote": "Ketika pasar besar bertemu operator yang tepat — hasilnya bukan pertumbuhan bertahap. Ini transformasional.", "execHeadline": "Satu peluang.\nPasar terbesar.\nStandar institusional.", "fundsHeading": "Strategi Penempatan\nModal", "heroCtaLabel": "Jadwalkan Pertemuan", "heroHeadline": "Bukan Sekadar Ide.\nNuzultrip Sudah Membuktikannya.\nRp11 M+ omzet kumulatif\n1.000+ jamaah telah diberangkatkan", "industryDesc": "Indonesia adalah pasar perjalanan religi terbesar di dunia — namun masih sangat terfragmentasi.", "revenueYear5": "Rp 52 M", "thankYouCity": "Makassar, Indonesia", "companyVision": "Menjadi perusahaan perjalanan Umrah paling terpercaya dan berstandar institusional di Indonesia pada 2029.", "execInfoBasis": "Makassar, Indonesia · Berdiri 2024", "footerIrLabel": "PPIU · Investor Relations", "footerTagline": "Operator perjalanan ibadah berstandar institusional.", "thankYouBadge": "CONFIDENTIAL · INVESTOR PRESENTATION · 2026", "thankYouEmail": "investor@nuzultrip.co.id", "thankYouPhone": "+62 21 XXXX XXXX", "thankYouTitle": "Terima Kasih", "thesisHeading": "Tiga Alasan untuk\nBerinvestasi Sekarang", "whyInvestDesc": "Nuzultrip hadir di persimpangan pasar besar, kesenjangan struktural, dan tim yang tepat.", "ctaSectionDesc": "Jadwalkan pertemuan, minta dokumen, atau hubungi tim Investor Relations kami langsung. Setiap interaksi dijamin kerahasiaan penuh.", "execInfoSektor": "Perjalanan Ibadah Umrah & Halal Tour", "footerNavTitle": "Portal", "instrumentRate": "12% per tahun", "instrumentType": "Convertible Note", "roadmapHeading": "Rencana Pertumbuhan Terstruktur", "competitiveDesc": "Nuzultrip dibangun dengan standar yang tidak dimiliki operator tradisional.", "ctaSecurityNote": "Semua interaksi dienkripsi dan dijaga kerahasiaannya sesuai standar NDA kami.", "equityTypeLabel": "Saham Biasa", "execInfoLisensi": "PPIU — Kementerian Haji dan Umrah", "footerCopyright": "© 2026 PT. Swarna Dipa Wisata. Seluruh hak cipta dilindungi. Operator PPIU berlisensi.", "heroDescription": "telah membangun bisnis perjalanan yang nyata, membukukan omzet kumulatif lebih dari Rp11 miliar, dan memberangkatkan lebih dari 1.000 jamaah.\nKini kami membuka kesempatan bagi 50 strategic partners untuk ikut memiliki bagian dari fase pertumbuhan Nuzultrip berikutnya.", "industryHeading": "Pasar Rp 25 Triliun yang\nMasih Kurang Terlayani", "instrumentTenor": "24 bulan", "revenueChartSub": "Rp Miliar · Skenario Dasar", "execInfoOperator": "PT. Swarna Dipa Wisata (Nuzultrip)", "footerDisclaimer": "Halaman ini ditujukan hanya untuk investor berkualifikasi dan tidak merupakan penawaran publik efek.", "returnDisclaimer": "Ini adalah proyeksi — bukan jaminan. Model keuangan lengkap tersedia di bawah NDA.", "segmentationDesc": "Nuzultrip melayani empat segmen jamaah berbeda dengan satu platform manajemen terintegrasi.", "thankYouSubtitle": "PT. Swarna Dipa Wisata · Nuzultrip", "whyInvestHeading": "Tiga Alasan untuk\nBerinvestasi Sekarang", "businessModelDesc": "Enam aliran pendapatan yang saling memperkuat, dikelola dalam satu platform terintegrasi.", "ctaSectionHeading": "Mulai Perjalanan Investasi Anda", "footerB